package com.onboardiq.api; import java.util.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api") public class ApiController { @GetMapping("/health") Map<String,String> health(){return Map.of("status","ok","service","onboardiq-api");} @GetMapping("/knowledge") List<Map<String,String>> knowledge(){return List.of(Map.of("id","employee-handbook","title","Employee Handbook","type","GUIDE"),Map.of("id","leave-policy","title","Leave Policy","type","POLICY"));} @PostMapping("/ai/chat") Map<String,Object> chat(){return Map.of("message","AI provider is not configured. Connect a RAG provider in the ai module before production use.","sources",List.of());} }
